import static org.junit.Assert.*;

public class Element_equals_TriageGen1Test {

    private Element element1;
    private Element element2;
    private Object nonElementObject;

    @Before
    public void setUp() {
        element1 = new Element(Tag.valueOf("div"), "http://example.com", new Attributes());
        element2 = new Element(Tag.valueOf("div"), "http://example.com", new Attributes());
        nonElementObject = new Object();
    }









    @Test
    public void testEqualsDifferentSuperClass() {
        Element superElement = new Element(Tag.valueOf("div"), "http://example.com", new Attributes()) {
            @Override
            public String nodeName() {
                return "SUPER_NODE";
            }
        };
        assertFalse(element1.equals(superElement));
    }






}

